import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { SlidersHorizontal, X } from 'lucide-react';
import ProductCard from '../components/ProductCard';
import api from '../services/api';
import './Products.css';

const CATEGORIES = ['All', 'Clothing', 'Toys', 'Feeding', 'Skincare', 'Gear', 'Safety', 'Newborn'];
const SORT_OPTIONS = [
  { value: '', label: 'Default' },
  { value: '-created_at', label: 'Newest First' },
  { value: 'price', label: 'Price: Low to High' },
  { value: '-price', label: 'Price: High to Low' },
  { value: '-rating', label: 'Top Rated' },
];

export default function Products() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [total, setTotal] = useState(0);
  const [showFilters, setShowFilters] = useState(false);

  const category = searchParams.get('category') || '';
  const search = searchParams.get('search') || '';
  const ordering = searchParams.get('ordering') || '';
  const minPrice = searchParams.get('min_price') || '';
  const maxPrice = searchParams.get('max_price') || '';

  useEffect(() => {
    setLoading(true);
    const params = new URLSearchParams();
    if (category && category !== 'All') params.set('category', category);
    if (search) params.set('search', search);
    if (ordering) params.set('ordering', ordering);
    if (minPrice) params.set('min_price', minPrice);
    if (maxPrice) params.set('max_price', maxPrice);

    api.get(`/products/?${params}`)
      .then(r => {
        setProducts(r.data.results || r.data);
        setTotal(r.data.count || (r.data.results || r.data).length);
      })
      .finally(() => setLoading(false));
  }, [category, search, ordering, minPrice, maxPrice]);

  const setParam = (key, value) => {
    const p = new URLSearchParams(searchParams);
    if (value) p.set(key, value); else p.delete(key);
    setSearchParams(p);
  };

  return (
    <div className="products-page">
      <div className="container">
        {/* Header */}
        <div className="products-header">
          <div>
            <h1 className="page-title">{category || search ? `${category || search}` : 'All Products'}</h1>
            <p className="result-count">{total} products found</p>
          </div>
          <div className="products-controls">
            <select value={ordering} onChange={e => setParam('ordering', e.target.value)} className="sort-select">
              {SORT_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
            </select>
            <button className="filter-toggle" onClick={() => setShowFilters(!showFilters)}>
              <SlidersHorizontal size={18} /> Filters
            </button>
          </div>
        </div>

        {/* Category Tabs */}
        <div className="category-tabs">
          {CATEGORIES.map(cat => (
            <button
              key={cat}
              className={`cat-tab ${(category === cat || (!category && cat === 'All')) ? 'active' : ''}`}
              onClick={() => setParam('category', cat === 'All' ? '' : cat)}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="products-layout">
          {/* Sidebar Filters */}
          <aside className={`filters-sidebar ${showFilters ? 'open' : ''}`}>
            <div className="filter-header">
              <h3>Filters</h3>
              <button onClick={() => setShowFilters(false)}><X size={20} /></button>
            </div>
            <div className="filter-group">
              <h4>Price Range</h4>
              <div className="price-inputs">
                <input type="number" placeholder="Min ₹" value={minPrice}
                  onChange={e => setParam('min_price', e.target.value)} />
                <span>-</span>
                <input type="number" placeholder="Max ₹" value={maxPrice}
                  onChange={e => setParam('max_price', e.target.value)} />
              </div>
            </div>
            <div className="filter-group">
              <h4>Category</h4>
              {CATEGORIES.slice(1).map(cat => (
                <label key={cat} className="filter-check">
                  <input type="radio" checked={category === cat}
                    onChange={() => setParam('category', cat)} />
                  {cat}
                </label>
              ))}
            </div>
            <button className="btn-outline" onClick={() => setSearchParams({})}>Clear All</button>
          </aside>

          {/* Grid */}
          <div className="products-main">
            {loading ? (
              <div className="products-grid">
                {Array(8).fill(0).map((_, i) => <div key={i} className="skeleton-card" />)}
              </div>
            ) : products.length ? (
              <div className="products-grid">
                {products.map(p => <ProductCard key={p.id} product={p} />)}
              </div>
            ) : (
              <div className="empty-state">
                <p>🔍 No products found. Try different filters.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
